-- Table structure for `gb_catalog_node`
DROP TABLE IF EXISTS `gb_catalog_node`;
CREATE TABLE `gb_catalog_node` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `node_type` varchar(16) NOT NULL COMMENT 'civil_code/biz_group/virtual_org/device/channel',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '父节点;根 NULL',
  `path` varchar(512) NOT NULL DEFAULT '/' COMMENT '物化路径 /12/47/189/',
  `depth` tinyint unsigned NOT NULL DEFAULT 0 COMMENT '深度,根=0',
  `name` varchar(128) NOT NULL COMMENT '节点显示名',
  `code` varchar(32) DEFAULT NULL COMMENT '节点编码(行政区 6/设备 20/通道 20)',
  `civil_code` varchar(6) DEFAULT NULL COMMENT '关联行政区(冗余加速过滤)',
  `device_id` bigint unsigned DEFAULT NULL COMMENT 'node_type=device 时引用',
  `channel_id` bigint unsigned DEFAULT NULL COMMENT 'node_type=channel 主挂载时引用',
  `source` varchar(16) NOT NULL DEFAULT 'catalog' COMMENT 'catalog/manual/auto',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '同级排序',
  `anomaly` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Q1:1=识别失败被兜底',
  `anomaly_reason` varchar(255) DEFAULT NULL COMMENT '兜底原因',
  `raw_code` varchar(64) DEFAULT NULL COMMENT '兜底前原始编码',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `owner_dept_id` int unsigned NOT NULL DEFAULT 0 COMMENT '所属部门ID',
  `alarm_resource_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_code` (`code`),
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_owner_dept_parent` (`owner_dept_id`, `parent_id`),
  KEY `idx_owner_dept_path` (`owner_dept_id`, `path`(128)),
  KEY `idx_owner_dept_type` (`owner_dept_id`, `node_type`),
  KEY `idx_owner_dept_anomaly` (`owner_dept_id`, `anomaly`),
  KEY `idx_owner_dept_civil_code` (`owner_dept_id`, `civil_code`),
  KEY `idx_catalog_alarm_resource` (`alarm_resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='国标多级目录树节点(思路 B+ 核心)';

-- Table structure for `gb_channel`
DROP TABLE IF EXISTS `gb_channel`;
CREATE TABLE `gb_channel` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `channel_id` varchar(20) NOT NULL DEFAULT '' COMMENT '通道国标编码',
  `device_id` varchar(20) NOT NULL DEFAULT '' COMMENT '所属设备国标编码',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '通道名称',
  `alias` varchar(255) NOT NULL DEFAULT '' COMMENT '用户自定义别名(用户可编辑,不被 Catalog 上报覆盖)',
  `manufacturer` varchar(255) NOT NULL DEFAULT '' COMMENT '厂商',
  `model` varchar(255) NOT NULL DEFAULT '' COMMENT '型号',
  `owner` varchar(64) NOT NULL DEFAULT '' COMMENT '设备归属',
  `civil_code` varchar(32) NOT NULL DEFAULT '' COMMENT '行政区划',
  `parent_id` varchar(20) NOT NULL DEFAULT '' COMMENT '父节点编码(目录树)',
  `ptz_type` tinyint DEFAULT 0 COMMENT '云台类型 0未知1球机2半球3固定枪机4遥控枪机',
  `longitude` decimal(10,6) DEFAULT '0.000000' COMMENT '经度',
  `latitude` decimal(10,6) DEFAULT '0.000000' COMMENT '纬度',
  `status` tinyint(1) DEFAULT 0 COMMENT '通道在线 0离线 1在线',
  `stream_id` varchar(64) NOT NULL DEFAULT '' COMMENT '当前播放流ID(ZLM app/stream),空=未点播',
  `current_ssrc` varchar(10) NOT NULL DEFAULT '' COMMENT '当前实时媒体会话SSRC',
  `on_demand_live` tinyint(1) NOT NULL DEFAULT 1 COMMENT '按需直播 1=无人观看自动关闭',
  `cloud_recording_enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '云端录像期望开关',
  `cloud_recording_state` varchar(20) NOT NULL DEFAULT 'disabled' COMMENT '云端录像运行状态',
  `cloud_recording_error` varchar(500) NOT NULL DEFAULT '' COMMENT '云端录像最近错误',
  `cloud_recording_updated_at` datetime DEFAULT NULL COMMENT '云端录像状态更新时间',
  `audio_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '点播是否接收音频',
  `stream_transport` varchar(16) NOT NULL DEFAULT 'TCP-Passive' COMMENT '流传输模式 UDP/TCP-Active/TCP-Passive',
  `capabilities` json DEFAULT NULL COMMENT '通道能力 {audio,h265,night_vision,alarm_io,recording}',
  `snapshot_url` varchar(500) NOT NULL DEFAULT '' COMMENT '通道最新快照 URL(相对路径,如 /uploads/gb-channel-snapshot/2026-07/xxx_yyy.jpg)',
  `snapshot_at` datetime DEFAULT NULL COMMENT '通道最新快照抓拍时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `owner_dept_id` int unsigned NOT NULL DEFAULT 0 COMMENT '所属部门ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_device_channel` (`device_id`, `channel_id`) USING BTREE,
  KEY `idx_device_id` (`device_id`),
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_owner_dept_deleted` (`owner_dept_id`, `deleted_at`),
  KEY `idx_stream_transport` (`stream_transport`),
  KEY `idx_stream_id` (`stream_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='GB28181国标通道表';

-- Table structure for `gb_channel_mount`
DROP TABLE IF EXISTS `gb_channel_mount`;
CREATE TABLE `gb_channel_mount` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `channel_id` bigint unsigned NOT NULL COMMENT '物理通道',
  `parent_node_id` bigint unsigned NOT NULL COMMENT '挂在哪个目录节点',
  `display_name` varchar(128) DEFAULT NULL COMMENT '挂载点别名,NULL=继承通道名',
  `is_primary` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=主挂载,每个 channel 必有且仅有一个',
  `mount_source` varchar(16) NOT NULL DEFAULT 'catalog' COMMENT 'catalog/manual',
  `sort_order` int NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `owner_dept_id` int unsigned NOT NULL DEFAULT 0 COMMENT '所属部门ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_channel_parent` (`channel_id`, `parent_node_id`),
  KEY `idx_parent_sort` (`parent_node_id`, `sort_order`),
  KEY `idx_owner_dept` (`owner_dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='通道与目录树节点的 N:N 挂载关系';

