-- Table structure for `gb_device`
DROP TABLE IF EXISTS `gb_device`;
CREATE TABLE `gb_device` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `device_id` varchar(20) NOT NULL DEFAULT '' COMMENT '20位国标编码',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '设备名称',
  `alias` varchar(255) NOT NULL DEFAULT '' COMMENT '用户自定义别名(用户可编辑,不被设备上报覆盖)',
  `password` varchar(255) NOT NULL DEFAULT '' COMMENT '按设备独立密码(本期用统一密码,留空)',
  `transport` varchar(8) NOT NULL DEFAULT '' COMMENT '传输模式 UDP/TCP',
  `manufacturer` varchar(255) NOT NULL DEFAULT '' COMMENT '厂商',
  `model` varchar(255) NOT NULL DEFAULT '' COMMENT '型号',
  `firmware` varchar(255) NOT NULL DEFAULT '' COMMENT '固件版本',
  `ip` varchar(64) NOT NULL DEFAULT '' COMMENT '设备来源IP',
  `port` int DEFAULT 0 COMMENT '设备来源端口',
  `register_time` datetime DEFAULT NULL COMMENT '最近注册成功时间',
  `register_expire_at` datetime DEFAULT NULL COMMENT '注册到期时刻',
  `keepalive_time` datetime DEFAULT NULL COMMENT '最近心跳时间',
  `keepalive_interval` int DEFAULT 60 COMMENT '【事实】期望心跳周期(秒)',
  `expires` int DEFAULT 0 COMMENT '注册有效期(秒)',
  `status` tinyint(1) DEFAULT 0 COMMENT '在线状态 0离线 1在线',
  `offline_at` datetime DEFAULT NULL COMMENT '最近被判离线的时刻',
  `subscribe_capability` varchar(16) NOT NULL DEFAULT 'unknown' COMMENT '订阅能力 unknown/subscribed/fallback',
  `subscribe_last_test` datetime DEFAULT NULL COMMENT '最近一次 SUBSCRIBE 尝试',
  `subscribe_expires_at` datetime DEFAULT NULL COMMENT '订阅过期时刻(提前续订)',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT 0 COMMENT '创建人',
  `owner_dept_id` int unsigned NOT NULL DEFAULT 0 COMMENT '所属部门ID',
  `reported_version` varchar(8) NOT NULL DEFAULT '' COMMENT '最近一次 X-GB-Ver 原始版本',
  `reported_version_at` datetime(3) DEFAULT NULL COMMENT '最近一次 X-GB-Ver 时间',
  `protocol_override` varchar(8) NOT NULL DEFAULT 'auto' COMMENT '协议版本覆盖 auto/2016/2022',
  `effective_version` varchar(8) NOT NULL DEFAULT 2016 COMMENT '当前生效协议版本',
  `effective_version_source` varchar(16) NOT NULL DEFAULT 'default' COMMENT '生效版本来源',
  `effective_version_at` datetime(3) DEFAULT NULL COMMENT '生效版本更新时间',
  `zlm_node_id` bigint NOT NULL DEFAULT 0 COMMENT '首选 ZLM 节点,0 表示自动调度',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_device_id` (`device_id`) USING BTREE,
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_status_keepalive` (`status`, `keepalive_time`),
  KEY `idx_subscribe_capability` (`subscribe_capability`, `subscribe_last_test`),
  KEY `idx_owner_dept_deleted` (`owner_dept_id`, `deleted_at`),
  KEY `idx_gb_device_zlm_node` (`zlm_node_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='GB28181国标设备表';

-- Table structure for `gb_device_control_state`
DROP TABLE IF EXISTS `gb_device_control_state`;
CREATE TABLE `gb_device_control_state` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `channel_id` bigint unsigned NOT NULL DEFAULT 0,
  `target_scope` varchar(16) NOT NULL,
  `target_code` varchar(20) NOT NULL,
  `record_state` varchar(8) NOT NULL DEFAULT 'unknown',
  `guard_state` varchar(8) NOT NULL DEFAULT 'unknown',
  `freshness` varchar(8) NOT NULL DEFAULT 'unknown',
  `observed_at` datetime(3) NOT NULL,
  `source` varchar(32) NOT NULL DEFAULT 'device_status',
  `source_sn` int NOT NULL DEFAULT 0,
  `source_operation_id` varchar(64) DEFAULT NULL,
  `source_operation_seq` bigint unsigned NOT NULL DEFAULT 0,
  `raw_summary` text,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_control_state_target` (`device_id`, `target_scope`, `target_code`),
  KEY `idx_control_state_device_target` (`device_id`, `target_scope`, `target_code`),
  KEY `idx_control_state_channel` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_device_status_event`
DROP TABLE IF EXISTS `gb_device_status_event`;
CREATE TABLE `gb_device_status_event` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` int unsigned NOT NULL COMMENT 'gb_device.id',
  `device_code` varchar(20) NOT NULL COMMENT 'device code snapshot',
  `event_type` varchar(32) NOT NULL COMMENT 'register_online/unregister_offline/heartbeat_timeout/heartbeat_recovered/register_renewed',
  `from_status` tinyint DEFAULT NULL COMMENT 'previous online status',
  `to_status` tinyint NOT NULL COMMENT 'resulting online status',
  `occurred_at` datetime NOT NULL COMMENT 'business event time',
  `source` varchar(32) NOT NULL COMMENT 'register/unregister/keepalive/offline_scanner',
  `register_expires` int DEFAULT NULL,
  `keepalive_interval` int DEFAULT NULL,
  `ip` varchar(64) NOT NULL DEFAULT '',
  `port` int NOT NULL DEFAULT 0,
  `transport` varchar(8) NOT NULL DEFAULT '',
  `detail` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_device_occurred` (`device_id`, `occurred_at`, `id`),
  KEY `idx_event_type_occurred` (`event_type`, `occurred_at`),
  KEY `idx_device_code` (`device_code`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='GB28181 device status event history';

-- Table structure for `gb_device_subscription`
DROP TABLE IF EXISTS `gb_device_subscription`;
CREATE TABLE `gb_device_subscription` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `device_id` int unsigned NOT NULL,
  `kind` varchar(32) NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(16) NOT NULL DEFAULT 'disabled',
  `expires_seconds` int NOT NULL DEFAULT 3600,
  `interval_seconds` int NOT NULL DEFAULT 0,
  `event` varchar(32) NOT NULL,
  `call_id` varchar(255) DEFAULT NULL,
  `local_tag` varchar(128) DEFAULT NULL,
  `remote_tag` varchar(128) DEFAULT NULL,
  `cseq` int unsigned NOT NULL DEFAULT 0,
  `expires_at` datetime DEFAULT NULL,
  `last_subscribe_at` datetime DEFAULT NULL,
  `last_notify_at` datetime DEFAULT NULL,
  `next_action_at` datetime DEFAULT NULL,
  `retry_count` int NOT NULL DEFAULT 0,
  `last_status_code` int NOT NULL DEFAULT 0,
  `last_error` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_device_subscription_kind` (`device_id`, `kind`),
  KEY `idx_subscription_call_id` (`call_id`),
  KEY `idx_subscription_due` (`enabled`, `next_action_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_mobile_position_history`
DROP TABLE IF EXISTS `gb_mobile_position_history`;
CREATE TABLE `gb_mobile_position_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` int unsigned NOT NULL,
  `source_code` varchar(20) NOT NULL,
  `channel_id` int unsigned DEFAULT NULL,
  `event_time` datetime NOT NULL,
  `received_at` datetime NOT NULL,
  `longitude` decimal(10,6) NOT NULL,
  `latitude` decimal(10,6) NOT NULL,
  `speed` double DEFAULT NULL,
  `direction` double DEFAULT NULL,
  `altitude` double DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_position_history_device_source_time` (`device_id`, `source_code`, `event_time`),
  KEY `idx_position_history_channel_time` (`channel_id`, `event_time`),
  KEY `idx_position_history_received_at` (`received_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_mobile_position_latest`
DROP TABLE IF EXISTS `gb_mobile_position_latest`;
CREATE TABLE `gb_mobile_position_latest` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `device_id` int unsigned NOT NULL,
  `source_code` varchar(20) NOT NULL,
  `channel_id` int unsigned DEFAULT NULL,
  `event_time` datetime NOT NULL,
  `received_at` datetime NOT NULL,
  `longitude` decimal(10,6) NOT NULL,
  `latitude` decimal(10,6) NOT NULL,
  `speed` double DEFAULT NULL,
  `direction` double DEFAULT NULL,
  `altitude` double DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_position_device_source` (`device_id`, `source_code`),
  KEY `idx_channel_id` (`channel_id`),
  KEY `idx_event_time` (`event_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_playback_scheme`
DROP TABLE IF EXISTS `gb_playback_scheme`;
CREATE TABLE `gb_playback_scheme` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `owner_user_id` bigint unsigned NOT NULL,
  `owner_dept_id` bigint unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `layout_size` smallint NOT NULL,
  `slot_count` int NOT NULL DEFAULT 0,
  `created_by` bigint unsigned NOT NULL,
  `updated_by` bigint unsigned NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_playback_scheme_owner_name` (`owner_user_id`, `name`),
  KEY `idx_playback_scheme_owner_updated` (`owner_user_id`, `updated_at`),
  KEY `idx_playback_scheme_dept` (`owner_dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_playback_scheme_slot`
DROP TABLE IF EXISTS `gb_playback_scheme_slot`;
CREATE TABLE `gb_playback_scheme_slot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `scheme_id` bigint unsigned NOT NULL,
  `slot_index` int NOT NULL,
  `device_code` varchar(20) NOT NULL,
  `channel_code` varchar(20) NOT NULL,
  `device_name_snapshot` varchar(255) NOT NULL,
  `channel_name_snapshot` varchar(255) NOT NULL,
  `created_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_playback_scheme_slot` (`scheme_id`, `slot_index`),
  KEY `idx_playback_scheme_slot_scheme` (`scheme_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_cruise_track`
DROP TABLE IF EXISTS `gb_ptz_cruise_track`;
CREATE TABLE `gb_ptz_cruise_track` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `channel_id` bigint unsigned NOT NULL,
  `track_id` int NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `enabled` tinyint(1) DEFAULT NULL,
  `detail_json` text,
  `last_operation_id` varchar(64) DEFAULT NULL,
  `raw_summary` text,
  `device_time` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_cruise_channel_track` (`channel_id`, `track_id`),
  KEY `idx_ptz_cruise_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_home_position`
DROP TABLE IF EXISTS `gb_ptz_home_position`;
CREATE TABLE `gb_ptz_home_position` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `channel_id` bigint unsigned NOT NULL,
  `channel_code` varchar(20) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  `reset_time` int DEFAULT NULL,
  `preset_id` int DEFAULT NULL,
  `enabled_encoding` varchar(32) NOT NULL DEFAULT 'numeric',
  `confirmed_at` datetime(3) NOT NULL,
  `source` varchar(32) NOT NULL,
  `verification` varchar(16) NOT NULL,
  `source_sn` int NOT NULL DEFAULT 0,
  `source_operation_id` varchar(64) DEFAULT NULL,
  `source_operation_seq` bigint unsigned NOT NULL DEFAULT 0,
  `raw_summary` text,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_home_position_channel` (`channel_id`),
  KEY `idx_ptz_home_position_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_operation`
DROP TABLE IF EXISTS `gb_ptz_operation`;
CREATE TABLE `gb_ptz_operation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `operation_id` varchar(64) NOT NULL,
  `idempotency_key` varchar(128) NOT NULL,
  `device_id` bigint unsigned NOT NULL,
  `device_code` varchar(20) NOT NULL,
  `channel_id` bigint unsigned NOT NULL,
  `channel_code` varchar(20) NOT NULL,
  `cmd_type` varchar(64) NOT NULL,
  `action` varchar(64) DEFAULT NULL,
  `payload_json` text,
  `sn` int NOT NULL,
  `call_id` varchar(255) DEFAULT NULL,
  `cseq` varchar(64) DEFAULT NULL,
  `sip_status` int NOT NULL DEFAULT 0,
  `device_result` varchar(32) DEFAULT NULL,
  `device_error` text,
  `status` varchar(16) NOT NULL,
  `attempt` int NOT NULL DEFAULT 1,
  `error_code` varchar(64) DEFAULT NULL,
  `error_message` text,
  `actor_id` bigint unsigned NOT NULL DEFAULT 0,
  `actor_dept_id` bigint unsigned NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL,
  `sent_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `response_required` tinyint(1) NOT NULL DEFAULT 0,
  `max_attempts` int NOT NULL DEFAULT 1,
  `queue_deadline_at` datetime(3) DEFAULT NULL,
  `dispatch_started_at` datetime(3) DEFAULT NULL,
  `transport_deadline_at` datetime(3) DEFAULT NULL,
  `deadline_at` datetime(3) DEFAULT NULL,
  `next_attempt_at` datetime(3) DEFAULT NULL,
  `response_call_id` varchar(255) DEFAULT NULL,
  `response_cseq` varchar(64) DEFAULT NULL,
  `response_at` datetime(3) DEFAULT NULL,
  `response_has_data` tinyint(1) DEFAULT NULL,
  `trigger_operation_id` varchar(64) DEFAULT NULL,
  `reconcile_operation_id` varchar(64) DEFAULT NULL,
  `profile_version` varchar(8) DEFAULT NULL,
  `profile_charset` varchar(16) DEFAULT NULL,
  `target_scope` varchar(16) DEFAULT NULL,
  `target_code` varchar(20) DEFAULT NULL,
  `scope_key` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_operation_id` (`operation_id`),
  UNIQUE KEY `uk_ptz_operation_idempotency` (`channel_id`, `idempotency_key`),
  KEY `idx_ptz_operation_channel_time` (`channel_id`, `created_at`),
  KEY `idx_ptz_operation_device_sn` (`device_id`, `sn`),
  KEY `idx_ptz_operation_status_time` (`status`, `created_at`),
  KEY `idx_ptz_operation_call_id` (`call_id`),
  KEY `idx_ptz_operation_channel_cmd_id` (`channel_id`, `cmd_type`, `id`),
  KEY `idx_ptz_operation_status_next_attempt` (`status`, `next_attempt_at`),
  KEY `idx_ptz_operation_status_queue_deadline` (`status`, `queue_deadline_at`),
  KEY `idx_ptz_operation_status_transport_deadline` (`status`, `transport_deadline_at`),
  KEY `idx_ptz_operation_status_deadline` (`status`, `deadline_at`),
  KEY `idx_ptz_operation_target` (`device_code`, `target_scope`, `target_code`, `status`),
  KEY `idx_ptz_operation_device_scope_time` (`device_id`, `scope_key`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_operation_attempt`
DROP TABLE IF EXISTS `gb_ptz_operation_attempt`;
CREATE TABLE `gb_ptz_operation_attempt` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `operation_id` bigint unsigned NOT NULL,
  `attempt_no` int NOT NULL,
  `sn` int NOT NULL,
  `status` varchar(16) NOT NULL,
  `call_id` varchar(255) DEFAULT NULL,
  `cseq` varchar(64) DEFAULT NULL,
  `sip_status` int NOT NULL DEFAULT 0,
  `started_at` datetime(3) NOT NULL,
  `lease_until` datetime(3) NOT NULL,
  `sent_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `error_code` varchar(64) DEFAULT NULL,
  `error_message` text,
  `created_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_operation_attempt` (`operation_id`, `attempt_no`),
  KEY `idx_ptz_attempt_status_lease` (`status`, `lease_until`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_preset`
DROP TABLE IF EXISTS `gb_ptz_preset`;
CREATE TABLE `gb_ptz_preset` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `channel_id` bigint unsigned NOT NULL,
  `preset_id` int NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'unknown',
  `last_operation_id` varchar(64) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_preset_channel_number` (`channel_id`, `preset_id`),
  KEY `idx_ptz_preset_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_ptz_state`
DROP TABLE IF EXISTS `gb_ptz_state`;
CREATE TABLE `gb_ptz_state` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `device_code` varchar(20) NOT NULL,
  `channel_id` bigint unsigned NOT NULL,
  `channel_code` varchar(20) NOT NULL,
  `pan` decimal(18,6) DEFAULT NULL,
  `tilt` decimal(18,6) DEFAULT NULL,
  `zoom` decimal(18,6) DEFAULT NULL,
  `focus` decimal(18,6) DEFAULT NULL,
  `iris` decimal(18,6) DEFAULT NULL,
  `device_time` datetime(3) DEFAULT NULL,
  `received_at` datetime(3) NOT NULL,
  `source_sn` int NOT NULL DEFAULT 0,
  `freshness` varchar(16) NOT NULL DEFAULT 'unknown',
  `dedupe_key` varchar(128) DEFAULT NULL,
  `raw_summary` text,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ptz_state_channel` (`channel_id`),
  KEY `idx_ptz_state_device` (`device_id`),
  KEY `idx_ptz_state_received` (`received_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='GB28181 latest PTZ state';;

-- Table structure for `gb_recording_file`
DROP TABLE IF EXISTS `gb_recording_file`;
CREATE TABLE `gb_recording_file` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_id` bigint unsigned DEFAULT NULL,
  `channel_id` int unsigned NOT NULL,
  `device_id` varchar(20) NOT NULL,
  `node_id` bigint NOT NULL,
  `vhost` varchar(128) NOT NULL,
  `app` varchar(64) NOT NULL,
  `stream` varchar(64) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_path` varchar(1000) NOT NULL,
  `folder` varchar(1000) NOT NULL DEFAULT '',
  `url` varchar(1000) NOT NULL DEFAULT '',
  `start_time` datetime DEFAULT NULL,
  `time_len` decimal(12,3) DEFAULT NULL,
  `file_size` bigint unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `channel_code` varchar(20) NOT NULL DEFAULT '' COMMENT '通道国标编码快照',
  `channel_name` varchar(255) NOT NULL DEFAULT '' COMMENT '通道名称快照',
  `device_name` varchar(255) NOT NULL DEFAULT '' COMMENT '设备名称快照',
  `owner_dept_id` bigint unsigned NOT NULL DEFAULT 0 COMMENT '归属部门快照',
  `file_key` varchar(64) NOT NULL,
  `source` varchar(16) NOT NULL DEFAULT 'hook' COMMENT 'hook/reconcile',
  `metadata_state` varchar(16) NOT NULL DEFAULT 'complete' COMMENT 'complete/partial',
  `record_date` date DEFAULT NULL COMMENT 'ZLM 目录日期',
  `discovered_at` datetime NOT NULL,
  `last_seen_at` datetime DEFAULT NULL COMMENT '最近确认存在时间',
  `missing_at` datetime DEFAULT NULL COMMENT '确认缺失时间',
  `reconcile_miss_count` int NOT NULL DEFAULT 0 COMMENT '连续对账未发现次数',
  `updated_at` datetime DEFAULT NULL COMMENT '索引更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_recording_file_key` (`file_key`),
  KEY `idx_recording_file_channel_start` (`channel_id`, `start_time`),
  KEY `idx_recording_file_device_start` (`device_id`, `start_time`),
  KEY `idx_recording_file_date_tuple` (`node_id`, `vhost`, `app`, `stream`, `record_date`),
  KEY `idx_recording_file_missing` (`missing_at`, `reconcile_miss_count`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='云端录像文件索引';

-- Table structure for `gb_recording_reconcile_state`
DROP TABLE IF EXISTS `gb_recording_reconcile_state`;
CREATE TABLE `gb_recording_reconcile_state` (
  `node_id` bigint NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'queued',
  `trigger_source` varchar(16) NOT NULL DEFAULT 'scheduled',
  `requested_start` datetime DEFAULT NULL,
  `requested_end` datetime DEFAULT NULL,
  `effective_start` datetime DEFAULT NULL,
  `effective_end` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `candidate_count` int NOT NULL DEFAULT 0,
  `success_count` int NOT NULL DEFAULT 0,
  `failure_count` int NOT NULL DEFAULT 0,
  `discovered_count` int NOT NULL DEFAULT 0,
  `inserted_count` int NOT NULL DEFAULT 0,
  `updated_count` int NOT NULL DEFAULT 0,
  `missing_count` int NOT NULL DEFAULT 0,
  `unattributed_count` int NOT NULL DEFAULT 0,
  `last_error` varchar(500) NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`node_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='云端录像节点最新对账状态';

-- Table structure for `gb_recording_session`
DROP TABLE IF EXISTS `gb_recording_session`;
CREATE TABLE `gb_recording_session` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `channel_id` int unsigned NOT NULL,
  `device_id` varchar(20) NOT NULL,
  `node_id` bigint NOT NULL,
  `vhost` varchar(128) NOT NULL DEFAULT '__defaultVhost__',
  `app` varchar(64) NOT NULL DEFAULT 'rtp',
  `stream` varchar(64) NOT NULL,
  `state` varchar(20) NOT NULL,
  `started_at` datetime DEFAULT NULL,
  `stopped_at` datetime DEFAULT NULL,
  `last_checked_at` datetime DEFAULT NULL,
  `last_error` varchar(500) NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_recording_session_media` (`node_id`, `vhost`, `app`, `stream`),
  KEY `idx_recording_session_channel_state` (`channel_id`, `state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='云端录像会话历史';

-- Table structure for `gb_sip_config`
DROP TABLE IF EXISTS `gb_sip_config`;
CREATE TABLE `gb_sip_config` (
  `id` tinyint unsigned NOT NULL COMMENT '单例主键，固定为 1',
  `deployment_mode` varchar(8) NOT NULL COMMENT 'lan/public',
  `listen_ip` varchar(45) NOT NULL COMMENT 'SIP 监听地址',
  `advertise_ip` varchar(45) NOT NULL COMMENT 'SIP 对外宣告地址',
  `advertise_ip_inferred` tinyint(1) NOT NULL DEFAULT 0 COMMENT '宣告地址是否由系统推断',
  `port` int unsigned NOT NULL COMMENT 'SIP 端口',
  `domain` varchar(10) NOT NULL COMMENT 'SIP 域',
  `server_id` varchar(20) NOT NULL COMMENT '平台国标编码',
  `password` varchar(255) NOT NULL COMMENT 'SIP Digest 原始凭据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  CONSTRAINT `chk_gb_sip_config_deployment_mode` CHECK ((`deployment_mode` in (_utf8mb4'lan',_utf8mb4'public'))),
  CONSTRAINT `chk_gb_sip_config_port` CHECK ((`port` between 1 and 65535)),
  CONSTRAINT `chk_gb_sip_config_singleton` CHECK ((`id` = 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='GB28181 SIP 运行时配置';

-- Table structure for `gb_sip_security_access_rule`
DROP TABLE IF EXISTS `gb_sip_security_access_rule`;
CREATE TABLE `gb_sip_security_access_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `list_type` varchar(16) NOT NULL,
  `match_type` varchar(16) NOT NULL,
  `match_value` varchar(255) NOT NULL,
  `scope` varchar(32) NOT NULL DEFAULT 'all_sip',
  `status` varchar(16) NOT NULL DEFAULT 'enabled',
  `expires_at` datetime DEFAULT NULL,
  `note` varchar(255) NOT NULL DEFAULT '',
  `created_by` varchar(64) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gb_sip_security_access_rule_match` (`list_type`, `match_type`, `match_value`),
  KEY `idx_gb_sip_security_access_rule_list_status` (`list_type`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `gb_sip_security_audit`
DROP TABLE IF EXISTS `gb_sip_security_audit`;
CREATE TABLE `gb_sip_security_audit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `actor` varchar(64) NOT NULL,
  `action` varchar(32) NOT NULL,
  `target` varchar(128) NOT NULL,
  `reason` varchar(255) NOT NULL,
  `decision_id` varchar(64) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_gb_sip_security_audit_time` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `gb_sip_security_ban`
DROP TABLE IF EXISTS `gb_sip_security_ban`;
CREATE TABLE `gb_sip_security_ban` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_ip` varchar(64) NOT NULL,
  `device_id` varchar(64) DEFAULT NULL,
  `risk_scope` varchar(16) DEFAULT NULL,
  `address_family` varchar(8) NOT NULL,
  `status` varchar(16) NOT NULL,
  `reason` varchar(32) NOT NULL,
  `rule_id` varchar(64) NOT NULL,
  `score` int NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  `expires_at` datetime DEFAULT NULL,
  `unbanned_at` datetime DEFAULT NULL,
  `unbanned_by` varchar(64) NOT NULL DEFAULT '',
  `origin` varchar(16) NOT NULL,
  `agent_state` varchar(16) NOT NULL,
  `decision_id` varchar(64) NOT NULL,
  `last_error` varchar(512) NOT NULL DEFAULT '',
  `trigger_method` varchar(16) NOT NULL DEFAULT '',
  `trigger_count` int NOT NULL DEFAULT 0,
  `trigger_threshold` int NOT NULL DEFAULT 0,
  `window_seconds` int NOT NULL DEFAULT 0,
  `policy_mode` varchar(16) NOT NULL DEFAULT '',
  `firewall_applied_at` datetime DEFAULT NULL,
  `blocked_count_after_ban` bigint NOT NULL DEFAULT 0,
  `last_blocked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gb_sip_security_ban_decision` (`decision_id`),
  KEY `idx_gb_sip_security_ban_source_status` (`source_ip`, `status`),
  KEY `idx_gb_sip_security_ban_attribution_status` (`risk_scope`, `device_id`, `status`),
  KEY `idx_gb_sip_security_ban_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `gb_sip_security_event`
DROP TABLE IF EXISTS `gb_sip_security_event`;
CREATE TABLE `gb_sip_security_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `bucket_at` datetime NOT NULL,
  `source_ip` varchar(64) NOT NULL,
  `device_id` varchar(64) DEFAULT NULL,
  `risk_scope` varchar(16) DEFAULT NULL,
  `address_family` varchar(8) NOT NULL,
  `transport` varchar(8) NOT NULL,
  `method` varchar(16) NOT NULL,
  `user_agent` varchar(255) NOT NULL DEFAULT '',
  `reason` varchar(32) NOT NULL,
  `action` varchar(16) NOT NULL,
  `count` bigint NOT NULL DEFAULT 0,
  `score_delta` bigint NOT NULL DEFAULT 0,
  `first_seen_at` datetime NOT NULL,
  `last_seen_at` datetime NOT NULL,
  `sample_event_id` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gb_sip_security_event` (`bucket_at`, `source_ip`, `device_id`, `risk_scope`, `transport`, `method`, `reason`, `action`),
  KEY `idx_gb_sip_security_event_source_time` (`source_ip`, `last_seen_at`),
  KEY `idx_gb_sip_security_event_attribution_time` (`risk_scope`, `device_id`, `last_seen_at`),
  KEY `idx_gb_sip_security_event_reason_time` (`reason`, `last_seen_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `gb_sip_security_policy`
DROP TABLE IF EXISTS `gb_sip_security_policy`;
CREATE TABLE `gb_sip_security_policy` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope_key` varchar(32) NOT NULL,
  `mode` varchar(16) NOT NULL,
  `window_seconds` int NOT NULL,
  `ban_score` int NOT NULL,
  `max_packet_bytes` int NOT NULL,
  `max_udp_per_window` int NOT NULL,
  `max_tcp_connections` int NOT NULL,
  `sample_per_source` int NOT NULL,
  `nonce_ttl_seconds` int NOT NULL,
  `ban_ttl_steps` varchar(1024) NOT NULL,
  `allowlist_text` varchar(4096) NOT NULL,
  `updated_by` bigint NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gb_sip_security_policy_scope` (`scope_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `gb_sip_trace_capture`
DROP TABLE IF EXISTS `gb_sip_trace_capture`;
CREATE TABLE `gb_sip_trace_capture` (
  `id` char(36) NOT NULL,
  `device_id` int unsigned NOT NULL,
  `device_code` varchar(20) NOT NULL,
  `created_by` int unsigned NOT NULL,
  `started_at` datetime(3) NOT NULL,
  `planned_end_at` datetime(3) NOT NULL,
  `ended_at` datetime(3) DEFAULT NULL,
  `end_reason` varchar(16) NOT NULL DEFAULT '',
  `active_key` varchar(64) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sip_trace_capture_active` (`active_key`),
  KEY `idx_sip_trace_capture_device_started` (`device_id`, `started_at`),
  KEY `idx_sip_trace_capture_device_code` (`device_code`),
  KEY `idx_sip_trace_capture_created_by` (`created_by`),
  KEY `idx_sip_trace_capture_planned_end` (`planned_end_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `gb_sip_trace_message`
DROP TABLE IF EXISTS `gb_sip_trace_message`;
CREATE TABLE `gb_sip_trace_message` (
  `event_id` varchar(36) NOT NULL,
  `occurred_at` datetime(6) NOT NULL,
  `direction` varchar(16) NOT NULL,
  `transport` varchar(16) NOT NULL,
  `local_addr` varchar(255) NOT NULL,
  `remote_addr` varchar(255) NOT NULL,
  `device_id` varchar(64) NOT NULL,
  `method` varchar(32) NOT NULL,
  `status_code` smallint unsigned NOT NULL,
  `call_id` varchar(255) NOT NULL,
  `cseq` int unsigned NOT NULL,
  `cseq_method` varchar(32) NOT NULL,
  `from_uri` varchar(512) NOT NULL,
  `to_uri` varchar(512) NOT NULL,
  `user_agent` varchar(512) NOT NULL,
  `malformed` tinyint(1) NOT NULL DEFAULT 0,
  `parse_error` varchar(1024) NOT NULL,
  `payload_nonce` blob NOT NULL,
  `payload_ciphertext` mediumblob NOT NULL,
  `payload_algorithm` varchar(32) NOT NULL,
  `payload_key_version` varchar(64) NOT NULL,
  `payload_digest_sha256` char(64) NOT NULL,
  PRIMARY KEY (`event_id`),
  KEY `idx_gb_sip_trace_occurred_event` (`occurred_at`, `event_id`),
  KEY `idx_gb_sip_trace_device_occurred` (`device_id`, `occurred_at`, `event_id`),
  KEY `idx_gb_sip_trace_call_occurred` (`call_id`, `occurred_at`, `event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_sip_trace_session_diagnosis`
DROP TABLE IF EXISTS `gb_sip_trace_session_diagnosis`;
CREATE TABLE `gb_sip_trace_session_diagnosis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_day` date NOT NULL,
  `observed_at` datetime(6) NOT NULL,
  `correlation_key` varchar(128) NOT NULL,
  `state` varchar(16) NOT NULL DEFAULT 'active',
  `category` varchar(32) NOT NULL,
  `code` varchar(64) NOT NULL,
  `stage` varchar(32) NOT NULL,
  `source` varchar(32) NOT NULL,
  `device_id` varchar(64) NOT NULL DEFAULT '',
  `channel_id` varchar(64) NOT NULL DEFAULT '',
  `call_id` varchar(255) NOT NULL DEFAULT '',
  `cseq` int unsigned NOT NULL DEFAULT 0,
  `method` varchar(32) NOT NULL DEFAULT '',
  `status_code` smallint unsigned NOT NULL DEFAULT 0,
  `stream_id` varchar(255) NOT NULL DEFAULT '',
  `resolved_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sip_trace_diagnosis_session` (`session_day`, `category`, `correlation_key`),
  KEY `idx_sip_trace_diagnosis_category_state_observed` (`session_day`, `category`, `state`, `observed_at`),
  KEY `idx_sip_trace_diagnosis_device_observed` (`device_id`, `observed_at`),
  KEY `idx_sip_trace_diagnosis_call_cseq` (`call_id`, `cseq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `gb_talk_session`
DROP TABLE IF EXISTS `gb_talk_session`;
CREATE TABLE `gb_talk_session` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(64) NOT NULL,
  `channel_id` int unsigned NOT NULL,
  `device_id` varchar(20) NOT NULL,
  `target_id` varchar(20) NOT NULL DEFAULT '',
  `actor_id` bigint unsigned NOT NULL DEFAULT 0,
  `actor_dept_id` bigint unsigned NOT NULL DEFAULT 0,
  `mode` varchar(16) NOT NULL DEFAULT 'talk',
  `broadcast_sn` bigint unsigned NOT NULL DEFAULT 0,
  `broadcast_reply_status` varchar(32) NOT NULL DEFAULT '',
  `signal_phase` varchar(40) NOT NULL DEFAULT '',
  `node_id` bigint NOT NULL DEFAULT 0,
  `app` varchar(64) NOT NULL DEFAULT 'talk',
  `source_stream` varchar(128) NOT NULL,
  `recv_stream` varchar(128) NOT NULL DEFAULT '',
  `ssrc` varchar(32) NOT NULL DEFAULT '',
  `state` varchar(20) NOT NULL,
  `lease_key` int unsigned DEFAULT NULL,
  `source_key` varchar(128) DEFAULT NULL,
  `recv_key` varchar(128) DEFAULT NULL,
  `ssrc_key` varchar(32) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `publish_token_hash` char(64) NOT NULL,
  `token_consumed_at` datetime DEFAULT NULL,
  `publish_id` varchar(255) NOT NULL DEFAULT '',
  `local_port` int NOT NULL DEFAULT 0,
  `remote_media_ip` varchar(64) NOT NULL DEFAULT '',
  `remote_media_port` int NOT NULL DEFAULT 0,
  `media_transport` varchar(16) NOT NULL DEFAULT '',
  `sender_mode` varchar(24) NOT NULL DEFAULT '',
  `call_id` varchar(255) NOT NULL DEFAULT '',
  `dialog_local_tag` varchar(128) NOT NULL DEFAULT '',
  `dialog_remote_tag` varchar(128) NOT NULL DEFAULT '',
  `dialog_remote_uri` varchar(512) NOT NULL DEFAULT '',
  `dialog_cseq` int unsigned NOT NULL DEFAULT 0,
  `error` varchar(500) NOT NULL DEFAULT '',
  `started_at` datetime DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_talk_session_session_id` (`session_id`),
  UNIQUE KEY `uk_talk_session_lease` (`lease_key`),
  UNIQUE KEY `uk_talk_session_source_key` (`source_key`),
  UNIQUE KEY `uk_talk_session_recv_key` (`recv_key`),
  UNIQUE KEY `uk_talk_session_ssrc_key` (`ssrc_key`),
  KEY `idx_talk_session_channel_created` (`channel_id`, `created_at`),
  KEY `idx_talk_session_state_expires` (`state`, `expires_at`),
  KEY `idx_talk_session_source` (`node_id`, `app`, `source_stream`),
  KEY `idx_talk_session_recv` (`node_id`, `recv_stream`),
  KEY `idx_talk_session_call_id` (`call_id`),
  KEY `idx_talk_session_broadcast_match` (`device_id`, `target_id`, `state`),
  KEY `idx_talk_session_broadcast_sn` (`broadcast_sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='GB28181 语音对讲会话历史';

-- Table structure for `meta_node`
DROP TABLE IF EXISTS `meta_node`;
CREATE TABLE `meta_node` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL DEFAULT '',
  `host` varchar(64) NOT NULL DEFAULT '',
  `receive_host` varchar(255) NOT NULL DEFAULT '',
  `playback_host` varchar(255) NOT NULL DEFAULT '',
  `api_port` int NOT NULL DEFAULT 18080,
  `api_secret` varchar(128) NOT NULL DEFAULT '',
  `media_server_uuid` varchar(64) NOT NULL DEFAULT '',
  `weight` int NOT NULL DEFAULT 50,
  `tags_json` text,
  `state` varchar(16) NOT NULL DEFAULT 'active',
  `rtp_port_start` int NOT NULL DEFAULT 30000,
  `rtp_port_end` int NOT NULL DEFAULT 35000,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_media_server_uuid` (`media_server_uuid`),
  KEY `idx_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ZLM 媒体节点表';

-- Table structure for `scheduler_log`
DROP TABLE IF EXISTS `scheduler_log`;
CREATE TABLE `scheduler_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `happened_at` datetime(3) NOT NULL,
  `algorithm` varchar(32) NOT NULL DEFAULT '',
  `node_id` bigint NOT NULL DEFAULT 0,
  `node_name` varchar(64) NOT NULL DEFAULT '',
  `stream_id` varchar(64) NOT NULL DEFAULT '',
  `device_id` varchar(64) NOT NULL DEFAULT '',
  `channel_id` varchar(64) NOT NULL DEFAULT '',
  `error_message` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_happened_at` (`happened_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ZLM 调度日志(异步写,7d 保留)';

-- Table structure for `scheduler_setting`
DROP TABLE IF EXISTS `scheduler_setting`;
CREATE TABLE `scheduler_setting` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `algorithm` varchar(32) NOT NULL DEFAULT 'roundrobin',
  `config_json` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='ZLM 调度器全局设置(单行)';

-- Table structure for `sys_affix`
DROP TABLE IF EXISTS `sys_affix`;
CREATE TABLE `sys_affix` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) DEFAULT NULL COMMENT '文件名',
  `path` varchar(255) DEFAULT NULL COMMENT '路径',
  `url` varchar(255) DEFAULT NULL COMMENT '文件url',
  `file_md5` varchar(32) DEFAULT '' COMMENT '文件MD5(秒传检测)',
  `size` int DEFAULT NULL COMMENT '文件大小',
  `ftype` varchar(100) DEFAULT NULL COMMENT '文件类型',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `suffix` varchar(100) DEFAULT NULL COMMENT '文件后缀',
  `thumbnail_path` varchar(255) DEFAULT NULL COMMENT '缩略图路径',
  `thumbnail_name` varchar(255) DEFAULT NULL COMMENT '缩略图名称',
  `thumbnail_url` varchar(255) DEFAULT NULL COMMENT '缩略图URL',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sys_affix_file_md5` (`file_md5`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_affix_chunk`
DROP TABLE IF EXISTS `sys_affix_chunk`;
CREATE TABLE `sys_affix_chunk` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `upload_id` varchar(64) NOT NULL COMMENT '上传会话ID',
  `file_md5` varchar(32) NOT NULL COMMENT '文件MD5',
  `file_name` varchar(255) DEFAULT NULL COMMENT '原始文件名',
  `file_size` bigint DEFAULT NULL COMMENT '文件总大小',
  `chunk_size` int DEFAULT NULL COMMENT '分片大小',
  `total_chunks` int DEFAULT NULL COMMENT '总分片数',
  `chunk_index` int NOT NULL COMMENT '当前分片序号',
  `chunk_path` varchar(255) DEFAULT NULL COMMENT '分片文件路径',
  `status` tinyint DEFAULT 0 COMMENT '0-上传中 1-已合并 2-已取消',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL COMMENT '创建者ID',
  PRIMARY KEY (`id`),
  KEY `idx_upload_id` (`upload_id`),
  KEY `idx_file_md5` (`file_md5`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_api`
DROP TABLE IF EXISTS `sys_api`;
CREATE TABLE `sys_api` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '权限名称',
  `path` varchar(255) DEFAULT NULL COMMENT '权限路径',
  `method` varchar(32) DEFAULT NULL COMMENT '请求方法',
  `api_group` varchar(255) DEFAULT NULL COMMENT '分组',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_casbin_rule`
DROP TABLE IF EXISTS `sys_casbin_rule`;
CREATE TABLE `sys_casbin_rule` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ptype` varchar(100) DEFAULT NULL,
  `v0` varchar(100) DEFAULT NULL,
  `v1` varchar(100) DEFAULT NULL,
  `v2` varchar(100) DEFAULT NULL,
  `v3` varchar(100) DEFAULT NULL,
  `v4` varchar(100) DEFAULT NULL,
  `v5` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `idx_casbin_rule` (`ptype`, `v0`, `v1`, `v2`, `v3`, `v4`, `v5`) USING BTREE,
  UNIQUE KEY `idx_sys_casbin_rule` (`ptype`, `v0`, `v1`, `v2`, `v3`, `v4`, `v5`)
) ENGINE=InnoDB AUTO_INCREMENT=7806 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_civil_code`
DROP TABLE IF EXISTS `sys_civil_code`;
CREATE TABLE `sys_civil_code` (
  `code` varchar(6) NOT NULL COMMENT '6 位 GB/T 2260 行政区码',
  `name` varchar(64) NOT NULL COMMENT '完整名称',
  `short_name` varchar(32) DEFAULT NULL,
  `parent_code` varchar(6) DEFAULT NULL,
  `level` tinyint NOT NULL COMMENT '1=省 2=市 3=区县',
  `pinyin` varchar(64) DEFAULT NULL COMMENT '拼音(Cmd+K 搜索)',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`code`),
  KEY `idx_parent_code` (`parent_code`, `level`),
  KEY `idx_pinyin` (`pinyin`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='行政区划字典 GB/T 2260';

-- Table structure for `sys_department`
DROP TABLE IF EXISTS `sys_department`;
CREATE TABLE `sys_department` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int unsigned DEFAULT 0 COMMENT '父级',
  `name` varchar(255) DEFAULT NULL COMMENT '部门名称',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态： 0 停用 1 启用',
  `leader` varchar(255) DEFAULT NULL COMMENT '负责人',
  `phone` varchar(255) DEFAULT NULL COMMENT '联系电话',
  `email` varchar(255) DEFAULT NULL COMMENT '邮箱',
  `sort` int DEFAULT 0 COMMENT '排序',
  `describe` varchar(255) DEFAULT NULL COMMENT '描述',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_dict`
DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) DEFAULT NULL COMMENT '字典名称',
  `code` varchar(255) DEFAULT NULL COMMENT '字典编码',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态',
  `description` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_dict_item`
DROP TABLE IF EXISTS `sys_dict_item`;
CREATE TABLE `sys_dict_item` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `value` varchar(255) DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL COMMENT '状态',
  `dict_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_gen`
DROP TABLE IF EXISTS `sys_gen`;
CREATE TABLE `sys_gen` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `db_type` varchar(255) DEFAULT NULL COMMENT '数据库类型',
  `database` varchar(255) DEFAULT NULL COMMENT '数据库',
  `name` varchar(255) DEFAULT NULL COMMENT '数据库表名',
  `module_name` varchar(255) DEFAULT NULL COMMENT '模块名称',
  `file_name` varchar(255) DEFAULT NULL COMMENT '文件名称',
  `describe` varchar(1000) DEFAULT NULL COMMENT '描述',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` int unsigned DEFAULT NULL COMMENT '创建人',
  `is_cover` tinyint DEFAULT 0 COMMENT '是否覆盖',
  `is_menu` tinyint DEFAULT 0 COMMENT '是否生成菜单',
  `is_tree` tinyint DEFAULT 0,
  `is_relation_tree` tinyint DEFAULT 0 COMMENT '是否关联树形分类',
  `relation_tree_table` int unsigned DEFAULT 0 COMMENT '关联的树形表',
  `relation_field` int unsigned DEFAULT 0 COMMENT '关联的字段ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_gen_field`
DROP TABLE IF EXISTS `sys_gen_field`;
CREATE TABLE `sys_gen_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `gen_id` int unsigned DEFAULT NULL,
  `data_name` varchar(255) DEFAULT NULL COMMENT '列名',
  `data_type` varchar(255) DEFAULT NULL COMMENT '数据类型',
  `data_comment` varchar(255) DEFAULT NULL COMMENT '列注释',
  `data_extra` varchar(255) DEFAULT NULL COMMENT '额外信息',
  `data_column_key` varchar(255) DEFAULT NULL COMMENT '列键信息',
  `data_unsigned` tinyint DEFAULT 0 COMMENT '是否为无符号类型',
  `is_primary` tinyint DEFAULT 0 COMMENT '是否主键',
  `go_type` varchar(255) DEFAULT NULL COMMENT 'go类型',
  `front_type` varchar(255) DEFAULT NULL COMMENT '前端类型',
  `custom_name` varchar(255) DEFAULT '' COMMENT '自定义字段名称',
  `require` tinyint DEFAULT 0 COMMENT '是否必填',
  `list_show` tinyint DEFAULT 0 COMMENT '列表显示',
  `form_show` tinyint DEFAULT 0 COMMENT '表单显示',
  `query_show` tinyint DEFAULT 0 COMMENT '查询显示',
  `query_type` varchar(255) DEFAULT NULL COMMENT '查询方式\r\nEQ  等于\r\nNE 不等于\r\nGT 大于\r\nGTE 大于等于\r\nLT 小于\r\nLTE 小于等于\r\nLIKE 包含\r\nBETWEEN 范围',
  `form_type` varchar(255) DEFAULT NULL COMMENT '表单类型\r\ninput 文本框\r\ntextarea 文本域\r\nnumber 数字输入框\r\nselect 下拉框\r\nradio 单选框\r\ncheckbox 复选框\r\ndatetime 日期时间',
  `dict_type` varchar(255) DEFAULT NULL COMMENT '关联的字典',
  `gorm_tag` varchar(255) DEFAULT NULL COMMENT 'gorm标签',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_job_results`
DROP TABLE IF EXISTS `sys_job_results`;
CREATE TABLE `sys_job_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `job_id` varchar(255) NOT NULL COMMENT '任务ID',
  `status` varchar(20) NOT NULL COMMENT '执行状态: SUCCESS, FAILED, PANIC',
  `error` text COMMENT '错误信息',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `duration` bigint NOT NULL COMMENT '执行时长(纳秒)',
  `retry_count` int NOT NULL DEFAULT 0 COMMENT '重试次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_job_id` (`job_id`),
  KEY `idx_status` (`status`),
  KEY `idx_start_time` (`start_time`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `sys_job_results_ibfk_1` FOREIGN KEY (`job_id`) REFERENCES `sys_jobs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务执行结果表';

-- Table structure for `sys_jobs`
DROP TABLE IF EXISTS `sys_jobs`;
CREATE TABLE `sys_jobs` (
  `id` varchar(255) NOT NULL COMMENT '任务ID',
  `group` varchar(100) NOT NULL COMMENT '任务分组名称',
  `name` varchar(200) NOT NULL COMMENT '任务名称',
  `description` text COMMENT '任务描述',
  `executor_name` varchar(100) NOT NULL COMMENT '执行器名称',
  `execution_policy` tinyint NOT NULL DEFAULT 1 COMMENT '执行策略: 0=单次执行, 1=重复执行',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '任务状态: 0=禁用, 1=启用',
  `cron_expression` varchar(100) NOT NULL COMMENT 'Cron表达式',
  `parameters` json DEFAULT NULL COMMENT '任务参数(JSON格式)',
  `blocking_policy` tinyint NOT NULL DEFAULT 0 COMMENT '阻塞策略: 0=丢弃, 1=覆盖, 2=并行',
  `timeout` bigint NOT NULL DEFAULT 30000000000 COMMENT '超时时间(纳秒)',
  `max_retry` int NOT NULL DEFAULT 0 COMMENT '最大重试次数',
  `retry_interval` bigint NOT NULL DEFAULT 10000000000 COMMENT '重试间隔(纳秒)',
  `parallel_num` int NOT NULL DEFAULT 1 COMMENT '并行数',
  `running_count` int NOT NULL DEFAULT 0 COMMENT '当前运行中的任务数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_group` (`group`),
  KEY `idx_status` (`status`),
  KEY `idx_executor_name` (`executor_name`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务调度表';

-- Table structure for `sys_menu`
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '路由ID',
  `parent_id` int unsigned NOT NULL DEFAULT 0 COMMENT '父级路由ID，顶层为0',
  `path` varchar(255) NOT NULL COMMENT '路由路径',
  `name` varchar(100) NOT NULL COMMENT '路由名称',
  `redirect` varchar(255) DEFAULT NULL COMMENT '重定向',
  `component` varchar(255) DEFAULT NULL COMMENT '组件文件路径',
  `title` varchar(100) DEFAULT NULL COMMENT '菜单标题，国际化key',
  `is_full` tinyint(1) DEFAULT 0 COMMENT '是否全屏显示：0-否，1-是',
  `hide` tinyint(1) DEFAULT 0 COMMENT '是否隐藏：0-否，1-是',
  `disable` tinyint(1) DEFAULT 0 COMMENT '是否停用：0-否，1-是',
  `keep_alive` tinyint(1) DEFAULT 0 COMMENT '是否缓存：0-否，1-是',
  `affix` tinyint(1) DEFAULT 0 COMMENT '是否固定：0-否，1-是',
  `link` varchar(500) DEFAULT '' COMMENT '外链地址',
  `iframe` tinyint(1) DEFAULT 0 COMMENT '是否内嵌：0-否，1-是',
  `svg_icon` varchar(100) DEFAULT '' COMMENT 'svg图标名称',
  `icon` varchar(100) DEFAULT '' COMMENT '普通图标名称',
  `sort` int DEFAULT 0 COMMENT '排序字段',
  `type` tinyint(1) DEFAULT 2 COMMENT '类型：1-目录，2-菜单，3-按钮',
  `is_link` tinyint(1) DEFAULT 0 COMMENT '是否外链',
  `permission` varchar(255) DEFAULT '' COMMENT '权限标识',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_parent_id` (`parent_id`) USING BTREE,
  KEY `idx_sort` (`sort`) USING BTREE,
  KEY `idx_type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统菜单路由表';

-- Table structure for `sys_menu_api`
DROP TABLE IF EXISTS `sys_menu_api`;
CREATE TABLE `sys_menu_api` (
  `menu_id` int unsigned NOT NULL,
  `api_id` int unsigned NOT NULL,
  PRIMARY KEY (`menu_id`,`api_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_operation_logs`
DROP TABLE IF EXISTS `sys_operation_logs`;
CREATE TABLE `sys_operation_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL COMMENT '操作用户ID',
  `username` varchar(50) DEFAULT NULL COMMENT '操作用户名',
  `module` varchar(100) DEFAULT NULL COMMENT '操作模块',
  `operation` varchar(100) DEFAULT NULL COMMENT '操作类型',
  `method` varchar(10) DEFAULT NULL COMMENT '请求方法',
  `path` varchar(500) DEFAULT NULL COMMENT '请求路径',
  `ip` varchar(50) DEFAULT NULL COMMENT '客户端IP',
  `user_agent` varchar(500) DEFAULT NULL COMMENT '用户代理',
  `request_data` text COMMENT '请求参数',
  `response_data` text COMMENT '响应数据',
  `status_code` int DEFAULT NULL COMMENT '响应状态码',
  `duration` bigint DEFAULT NULL COMMENT '操作耗时(毫秒)',
  `error_msg` text COMMENT '错误信息',
  `location` varchar(100) DEFAULT NULL COMMENT '操作地点',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sys_operation_logs_deleted_at` (`deleted_at`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统操作日志表';

-- Table structure for `sys_param`
DROP TABLE IF EXISTS `sys_param`;
CREATE TABLE `sys_param` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL COMMENT '参数名称',
  `code` varchar(255) NOT NULL COMMENT '参数唯一标识',
  `value` text COMMENT '参数值',
  `status` tinyint DEFAULT 1 COMMENT '状态(0禁用/1启用)',
  `description` varchar(500) DEFAULT NULL COMMENT '描述',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_param_code` (`code`),
  KEY `idx_sys_param_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统参数配置';

-- Table structure for `sys_role`
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT '' COMMENT '角色名称',
  `sort` int DEFAULT 0 COMMENT '排序',
  `status` tinyint DEFAULT 0 COMMENT '状态',
  `description` varchar(255) DEFAULT NULL COMMENT '描述',
  `parent_id` int unsigned DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `data_scope` int DEFAULT 0 COMMENT '数据权限',
  `checked_depts` varchar(1000) DEFAULT NULL COMMENT '数据权限关联的部门',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_role_menu`
DROP TABLE IF EXISTS `sys_role_menu`;
CREATE TABLE `sys_role_menu` (
  `role_id` int unsigned NOT NULL,
  `menu_id` int unsigned NOT NULL,
  PRIMARY KEY (`role_id`,`menu_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_user_role`
DROP TABLE IF EXISTS `sys_user_role`;
CREATE TABLE `sys_user_role` (
  `user_id` int unsigned NOT NULL DEFAULT 0 COMMENT '用户ID',
  `role_id` int unsigned NOT NULL DEFAULT 0 COMMENT '角色ID',
  PRIMARY KEY (`user_id`,`role_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table structure for `sys_users`
DROP TABLE IF EXISTS `sys_users`;
CREATE TABLE `sys_users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL DEFAULT '' COMMENT '用户名',
  `password` varchar(255) NOT NULL DEFAULT '' COMMENT '密码',
  `email` varchar(100) DEFAULT '' COMMENT '邮箱',
  `status` tinyint(1) DEFAULT 1 COMMENT '是否启用 0停用 1启用',
  `dept_id` int unsigned DEFAULT 0 COMMENT '部门ID',
  `phone` varchar(64) DEFAULT '' COMMENT '电话',
  `sex` varchar(64) DEFAULT '' COMMENT '性别',
  `nick_name` varchar(100) DEFAULT '' COMMENT '昵称',
  `avatar` varchar(255) DEFAULT '' COMMENT '头像',
  `description` varchar(500) DEFAULT NULL COMMENT '描述',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT 0 COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `username` (`username`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;

